<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$action=$_POST['action']??'';if($action==='block')$pdo->prepare("UPDATE users SET status='blocked' WHERE id=?")->execute([$id]);elseif($action==='unblock')$pdo->prepare("UPDATE users SET status='active' WHERE id=?")->execute([$id]);elseif($action==='role')$pdo->prepare("UPDATE users SET role=? WHERE id=?")->execute([$_POST['role']==='admin'?'admin':'customer',$id]);elseif($action==='delete')$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('Utilisateur mis à jour');redirect_self();}
$q=trim((string)($_GET['q']??''));$sql='SELECT u.id,u.email,u.role,u.status,u.created_at,COUNT(o.id) orders_count,COALESCE(SUM(CASE WHEN o.payment_status="paid" THEN o.amount ELSE 0 END),0) spent FROM users u LEFT JOIN orders o ON o.customer_email=u.email';$params=[];if($q!==''){$sql.=' WHERE u.email LIKE ?';$params[]='%'.$q.'%';}$sql.=' GROUP BY u.id ORDER BY u.id DESC';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();admin_layout_start('Utilisateurs');echo '<form class="form" method="get"><input name="q" value="'.h($q).'" placeholder="Rechercher par email"><button>Rechercher</button></form><table><tr><th>ID</th><th>Email</th><th>Rôle</th><th>Statut</th><th>Commandes</th><th>Dépensé</th><th>Actions</th></tr>';foreach($rows as $r){echo '<tr><td>'.h($r['id']).'</td><td>'.h($r['email']).'</td><td><form method="post"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($r['id']).'"><input type="hidden" name="action" value="role"><select name="role" onchange="this.form.submit()"><option value="customer" '.($r['role']==='customer'?'selected':'').'>customer</option><option value="admin" '.($r['role']==='admin'?'selected':'').'>admin</option></select></form></td><td>'.h($r['status']).'</td><td>'.h($r['orders_count']).'</td><td>'.h($r['spent']).'</td><td><form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($r['id']).'"><input type="hidden" name="action" value="'.($r['status']==='active'?'block':'unblock').'"><button>'.($r['status']==='active'?'Bloquer':'Débloquer').'</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($r['id']).'"><input type="hidden" name="action" value="delete"><button onclick="return confirm(\'Supprimer cet utilisateur ?\')">Supprimer</button></form></td></tr>'; }echo '</table>';admin_layout_end();